-- 300 questions: 10 questions for each of the 30 companies.
-- 5 coding questions per company include input/output formats.
-- Run schema/migration first, then run this file.

ALTER TABLE questions ADD COLUMN IF NOT EXISTS input_format TEXT;
ALTER TABLE questions ADD COLUMN IF NOT EXISTS output_format TEXT;
ALTER TABLE companies ADD COLUMN IF NOT EXISTS logo_url TEXT;

